/bin/bash -lc "cd [workspace path] && python << 'EOF'
import numpy as np
from scipy import ndimage
d = np.load('source_pixels.npz')['rgb']

def track_color(d, kind):
    pos = []
    prev = None
    for fi in range(96):
        f = d[fi].astype(int)
        r,g,b = f[:,:,0],f[:,:,1],f[:,:,2]
        if kind=='red':
            m = (r>170)&(r-g>60)&(r-b>60)
        else:
            m = (b>130)&(b-r>30)&(b-g>20)
        # ROI: table area
        mask = np.zeros_like(m); mask[35:115, 15:245] = True
        m &= mask
        lab,n = ndimage.label(m)
        best=None
        if n:
            sizes = ndimage.sum(m, lab, range(1,n+1))
            cents = ndimage.center_of_mass(m, lab, range(1,n+1))
            for s,(y,x) in zip(sizes,cents):
                if s<8: continue
                if prev is None or best is None or ((x-prev[0])**2+(y-prev[1])**2) < best[0]:
                    best = (((x-prev[0])**2+(y-prev[1])**2) if prev is not None else 0, x, y, s)
        if best:
            prev = (best[1],best[2])
            pos.append((best[1],best[2],best[3]))
        else:
            pos.append((np.nan,np.nan,0))
    return np.array(pos)

for kind in ['red','blue']:
    p = track_color(d, kind)
    print(kind)
    for i in range(0,96,6):
        print(i, np.round(p[i],1))
EOF"
